from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from .api.routes import router
from .api.signals import router as signals_router
from .api.live import router as live_router
from .db import init_db

app=FastAPI(title="Qanas Data Engine",version="0.5.1")
@app.on_event("startup")
def startup(): init_db()
app.include_router(router,prefix="/api")
app.include_router(signals_router,prefix="/api")
app.include_router(live_router,prefix="/api")

DASHBOARD_HTML=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>قنص · QANAS</title><style>
:root{--bg:#05090d;--panel:#091119;--line:#172631;--text:#f3f6f7;--muted:#71828e;--gold:#d8b468;--green:#42d392;--cyan:#58bce8;--amber:#f2a94b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Segoe UI,Tahoma,Arial;font-size:13px}.wrap{max-width:100%;padding:10px 12px}.top,.toolbar,.actions,.chips,.brand,.quick{display:flex;gap:8px;align-items:center}.top{justify-content:space-between;height:48px;margin-bottom:8px}.brand{min-width:170px}.mark{width:36px;height:36px;border:1px solid #755f36;border-radius:9px;display:grid;place-items:center;color:var(--gold);font-size:18px;font-weight:900;background:#11150f}.brand h1{font-size:19px;margin:0}.brand small{font-size:9px;color:var(--muted)}.btn,.chip{border:1px solid var(--line);background:#09131a;color:var(--text);border-radius:8px;cursor:pointer}.btn{padding:8px 10px}.btn.gold,.chip.active{background:#c9a75e;color:#080a0b;border-color:#c9a75e;font-weight:800}.quick{border:1px solid var(--line);background:#071017;border-radius:10px;padding:7px 10px;margin-bottom:8px;overflow:auto}.qstat{display:flex;align-items:center;gap:6px;padding:0 10px;border-left:1px solid var(--line);white-space:nowrap}.qstat:last-child{border-left:0}.qstat span{font-size:10px;color:var(--muted)}.qstat b{font-size:14px}.good,.rise,.live{color:var(--green);font-weight:800}.nearready{color:var(--amber);font-weight:800}.goldtext{color:var(--gold);font-weight:800}.rebate{color:var(--cyan);font-weight:800}.toolbar{justify-content:space-between;border:1px solid var(--line);background:#071017;padding:6px;border-radius:10px;margin-bottom:6px;position:sticky;top:0;z-index:30}.search{min-width:230px;flex:1}.search input{width:100%;height:34px;background:#040a0e;border:1px solid #1a2c37;color:white;border-radius:7px;padding:0 10px}.chips{white-space:nowrap;overflow:auto}.chip{padding:7px 9px;font-size:11px}.tablebox{border:1px solid var(--line);border-radius:9px;overflow:auto;background:#060c11;max-height:calc(100vh - 118px)}table{width:100%;border-collapse:separate;border-spacing:0;min-width:1450px;font-variant-numeric:tabular-nums}th,td{padding:7px 8px;border-bottom:1px solid #12212b;text-align:right;white-space:nowrap;height:43px}th{height:34px;font-size:9px;color:#748692;background:#081119;position:sticky;top:0;z-index:20}tbody tr{cursor:pointer}tbody tr:hover{background:#0d1921}.ticker{font-size:14px;font-weight:900}.company{font-size:8px;color:var(--muted);max-width:120px;overflow:hidden;text-overflow:ellipsis}.tickercol{position:sticky;right:0;z-index:12;background:#071017;box-shadow:-1px 0 #1b2b36}.tickerhead{z-index:25}.readybadge{display:inline-flex;min-width:55px;justify-content:center;padding:4px 7px;border-radius:6px;font-weight:900}.ready100{background:#123026;color:#5be0a5;border:1px solid #285944}.ready90{background:#322514;color:#ffc468;border:1px solid #624724}.ready80{background:#292419;color:#d7b66d;border:1px solid #504329}.progress{width:58px;height:2px;background:#1a2730;margin-top:3px}.progress i{display:block;height:100%;background:var(--green)}.pill{border:1px solid #263947;padding:3px 5px;border-radius:5px}.missing{max-width:310px;overflow:hidden;text-overflow:ellipsis}.empty{text-align:center;padding:45px;color:var(--muted)}.drawer{position:fixed;inset:0;background:#000b;display:none;z-index:50}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(540px,94vw);background:#071017;border-right:1px solid #263744;padding:20px;overflow:auto}.close{float:left;background:#101b23;border:1px solid var(--line);border-radius:7px;color:white;font-size:20px;width:34px;height:34px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:12px}.mini{background:#0a141c;border:1px solid var(--line);border-radius:8px;padding:10px}.mini span{display:block;color:var(--muted);font-size:9px;margin-bottom:4px}.histrow{display:grid;grid-template-columns:1.3fr .8fr .8fr .8fr;gap:7px;padding:7px;border-bottom:1px solid var(--line);font-size:11px}.toast{position:fixed;bottom:15px;right:15px;background:#102019;padding:10px;border:1px solid #31553f;border-radius:8px;display:none}.toast.show{display:block}@media(max-width:900px){.wrap{padding:6px}.top{height:auto}.brand small{display:none}.actions .btn:first-child{display:none}.quick{flex-wrap:nowrap}.tablebox{max-height:none}.missing{max-width:220px}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="mark">ق</div><div><h1>قنص</h1><small>QANAS · LIVE TERMINAL</small></div></div><div class="actions"><span id="syncState" class="good">● متصل</span><button class="btn" onclick="loadData()">↻ تحديث</button><button id="borrowBtn" class="btn gold" onclick="startBorrowSync()">Borrow تحديث</button></div></div><div class="quick"><div class="qstat"><span>الأسهم</span><b id="sTotal">—</b></div><div class="qstat"><span>Available ≤10K</span><b id="sScarce">—</b></div><div class="qstat"><span>قرب القاع ≤10%</span><b id="sNear">—</b></div><div class="qstat"><span>وصل النصف</span><b id="sHalf">—</b></div><div class="qstat"><span>🎯 الأجهز</span><b id="sReady">—</b></div><div class="qstat"><span>آخر Borrow</span><b id="lastBorrow" style="font-size:10px">—</b></div><div class="qstat"><span>السعر</span><b class="live" style="font-size:10px">LIVE + ممتد</b></div></div><div class="toolbar"><div class="search"><input id="q" placeholder="ابحث بالرمز أو الشركة..." oninput="render()"></div><div class="chips"><button class="chip active" onclick="setFilter('all',this)">الكل</button><button class="chip" onclick="setFilter('ready',this)">🎯 الأجهز</button><button class="chip" onclick="setFilter('launched',this)">🚀 +40%</button><button class="chip" onclick="setFilter('scarce',this)">Available منخفض</button><button class="chip" onclick="setFilter('near',this)">قرب القاع</button><button class="chip" onclick="setFilter('half',this)">النصف</button></div></div><div class="tablebox"><table><thead><tr><th class="tickercol tickerhead">السهم</th><th>الجاهزية</th><th>Available</th><th>CTB</th><th>Rebate</th><th>LIVE</th><th>القاع</th><th>عن القاع</th><th>القمة</th><th>النصف</th><th>الثبات</th><th>بعد الجاهزية</th><th>وش باقي؟</th><th>التاريخ</th><th>التقسيم</th></tr></thead><tbody id="rows"></tbody></table></div></div><div id="drawer" class="drawer" onclick="if(event.target===this)closeDrawer()"><div class="sheet"><button class="close" onclick="closeDrawer()">×</button><div id="detail"></div></div></div><div id="toast" class="toast"></div><script>
let data=[],signals={},live={},filter='all';const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>n==null?'—':'$'+Number(n).toFixed(4),pct=n=>n==null?'—':Number(n).toFixed(2)+'%';function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}function setFilter(f,e){filter=f;document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));e.classList.add('active');render()}async function loadData(){try{syncState.textContent='● تحديث...';const [d,s,l]=await Promise.all([fetch('/api/hunt').then(r=>r.json()),fetch('/api/signals').then(r=>r.json()),fetch('/api/live-prices').then(r=>r.json())]);signals=Object.fromEntries(s.map(x=>[x.symbol,x]));live=Object.fromEntries(l.map(x=>[x.symbol,x]));data=d.map(x=>({...x,signal:signals[x.symbol]||null,live:live[x.symbol]||null}));syncState.textContent='● متصل';summary();render()}catch(e){syncState.textContent='● خطأ'}}function summary(){sTotal.textContent=data.length;sScarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;sHalf.textContent=data.filter(x=>x.half_level_reached).length;sNear.textContent=data.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10).length;sReady.textContent=data.filter(x=>x.signal?.ready||x.signal?.near_ready).length;const d=data.map(x=>x.borrow_timestamp).filter(Boolean).sort().pop();lastBorrow.textContent=d?new Date(d+'Z').toLocaleString('ar-SA'):'—'}function rank(x){return x.signal?.ready?100:Number(x.signal?.readiness_pct??x.ready_score??0)}function render(){let a=data,q=document.getElementById('q').value.trim().toUpperCase();a=a.filter(x=>!q||x.symbol.includes(q)||(x.company||'').toUpperCase().includes(q));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='half')a=a.filter(x=>x.half_level_reached);if(filter==='near')a=a.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10);if(filter==='ready')a=a.filter(x=>x.signal?.ready||x.signal?.near_ready);if(filter==='launched')a=a.filter(x=>x.signal?.launched);a.sort((a,b)=>filter==='launched'?(b.signal?.rise_pct||0)-(a.signal?.rise_pct||0):filter==='ready'?(rank(b)-rank(a)||((a.available??1e12)-(b.available??1e12))||((a.distance_from_low_pct??1e9)-(b.distance_from_low_pct??1e9))):(b.ready_score||0)-(a.ready_score||0));rows.innerHTML=a.length?a.map(x=>{let s=x.signal,dt=s?.launched_at||s?.ready_at,lp=x.live?.live_price,shown=lp??x.current_price,r=rank(x),status=s?.ready?'100% 🎯':s?.near_ready?`${fmt(r)}%`:'—',cls=r>=100?'ready100':r>=90?'ready90':'ready80',missing=s?.ready?'مكتمل ✓':s?.missing||'—';return `<tr onclick="openStock('${x.symbol}')"><td class="tickercol"><b class="ticker">${x.symbol}</b><div class="company">${x.company||''}</div></td><td>${s?.ready||s?.near_ready?`<span class="readybadge ${cls}">${status}</span><div class="progress"><i style="width:${Math.min(100,r)}%"></i></div>`:`${fmt(x.ready_score)}%`}</td><td class="${x.available<=10000?'good':''}">${fmt(x.available)}</td><td class="goldtext">${pct(x.ctb)}</td><td class="rebate">${pct(x.rebate_rate)}</td><td class="${lp!=null?'live':''}">${money(shown)}<div class="company">${lp!=null?'LIVE · ممتد':'إغلاق'}</div></td><td>${money(x.post_split_low)}</td><td>${pct(x.distance_from_low_pct)}</td><td>${money(x.post_split_high)}</td><td><span class="pill">${money(x.half_level)} ${x.half_level_reached?'✓':''}</span></td><td>${fmt(x.stability_sessions)}/4</td><td class="rise">${s?.rise_pct!=null?pct(s.rise_pct):'—'}</td><td class="missing ${s?.near_ready?'nearready':''}" title="${missing}">${missing}</td><td>${dt?new Date(dt+'Z').toLocaleDateString('ar-SA'):'—'}<div class="company">${s?.launched?'🚀':s?.ready?'🎯':s?.near_ready?'قريب جدًا':''}</div></td><td>${x.ratio}<div class="company">${x.effective_date}</div></td></tr>`}).join(''):'<tr><td colspan="15" class="empty">لا توجد نتائج</td></tr>'}async function openStock(symbol){drawer.classList.add('open');detail.innerHTML='<div class="empty">جاري التحميل...</div>';try{const [s,h]=await Promise.all([fetch('/api/stock/'+symbol).then(r=>r.json()),fetch('/api/borrow/'+symbol+'/history?limit=12').then(r=>r.json())]),g=signals[symbol],l=live[symbol];detail.innerHTML=`<div class="goldtext">QANAS / STOCK</div><h2 style="font-size:30px;margin:4px 0">${s.symbol}</h2><div style="color:var(--muted)">${s.company||''}</div>${g?.missing?`<div class="mini nearready" style="margin-top:12px"><span>وش باقي؟</span><b>${g.missing}</b></div>`:''}${g?.strength?`<div class="mini good" style="margin-top:7px"><span>نقاط القوة</span><b>${g.strength}</b></div>`:''}<div class="grid2"><div class="mini"><span>LIVE</span><b class="live">${money(l?.live_price??s.current_price)}</b></div><div class="mini"><span>آخر إغلاق</span><b>${money(s.current_price)}</b></div><div class="mini"><span>Available</span><b>${fmt(s.available)}</b></div><div class="mini"><span>CTB</span><b class="goldtext">${pct(s.ctb)}</b></div><div class="mini"><span>Rebate</span><b class="rebate">${pct(s.rebate_rate)}</b></div><div class="mini"><span>عن القاع</span><b>${pct(s.distance_from_low_pct)}</b></div><div class="mini"><span>الثبات</span><b>${fmt(s.stability_sessions)}/4</b></div><div class="mini"><span>النصف</span><b>${money(s.half_level)} ${s.half_level_reached?'✓':''}</b></div><div class="mini"><span>بعد الجاهزية</span><b class="rise">${g?.rise_pct!=null?pct(g.rise_pct):'—'}</b></div><div class="mini"><span>أعلى 4H</span><b>${pct(s.four_hour_highest_rise_pct)}</b></div></div><h3>Borrow History</h3>${h.map(r=>`<div class="histrow"><span>${new Date(r.timestamp+'Z').toLocaleString('ar-SA')}</span><b>${fmt(r.available)}</b><b>${pct(r.ctb)}</b><b class="rebate">${pct(r.rebate_rate)}</b></div>`).join('')}`}catch(e){detail.innerHTML='تعذر التحميل'}}function closeDrawer(){drawer.classList.remove('open')}async function startBorrowSync(){borrowBtn.disabled=true;await fetch('/api/sync/borrow/all');pollBorrow()}async function pollBorrow(){const s=await fetch('/api/sync/borrow/status').then(r=>r.json());borrowBtn.textContent=s.running?`${s.processed}/${s.total}`:'Borrow تحديث';if(s.running)setTimeout(pollBorrow,1500);else{borrowBtn.disabled=false;toast('اكتمل التحديث');loadData()}}loadData();setInterval(loadData,60000);
</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard(): return HTMLResponse(DASHBOARD_HTML)
